}

/* 6. 隐秘幻想折叠卡片 (彻底修复点击失效问题！) */
.xt-collapse-1 {
  display: block !important; margin: 0 !important; padding: 0 !important; border: none !important;
}
/* 伪装成订阅按钮，绝对定位在右上角 */
.xt-collapse-1 .xt-collapse-header {
