/* 卡片内的文字 */
.xt-text-ft { color: #0f0f0f !important; font-size: 13px !important; line-height: 1.5 !important; margin: 0 !important; }
.xt-text-ft::before {
  content: "隐秘幻想"; display: flex; align-items: center; color: #FF0000; font-weight: bold; font-size: 14px; margin-bottom: 6px;
