  background-size: 16px; background-repeat: no-repeat; background-position: left center; padding-left: 22px;
}

/* 7. 评论区与动态全局样式 */
.xt-text-vc1, .xt-text-vc2, .xt-text-vc3, .xt-text-pc1, .xt-text-pc2, .xt-text-pc3 {
