xinshengCustomCss:
.xt-root {
  --xt-bg: #fff;
  --xt-text: #222;
  --xt-text-sub: #777;
  --xt-text-muted: #aaa;
  --xt-accent: #3b4f76;
  --xt-border: #e8e8e8;
  --xt-radius: 14px;
  --xt-radius-sm: 0;
  --xt-font: -apple-system, "PingFang SC", "Noto Sans KR", "Malgun Gothic", "Helvetica Neue", Arial, sans-serif;
  position: relative;
  padding-top: 52px;
  overflow: hidden;
}

/*⁣‍‌‌⁠‍‍⁠​​‌⁠​‌​​⁠⁠⁠‍‍⁠​​⁠⁠⁠​‍‌‌⁠⁠‍‌‌​‍⁠⁠​⁠‌⁠​‍⁠‌⁠‌‌​‍​‌‌‍‌⁠​‌‍‍‌​⁣ 顶部深蓝导航条 + logo */
.xt-root::before {
  content: "theqoo";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 52px;
  line-height: 52px;
  padding-left: 62px;
  background: #3b4f76;
  color: #fff;
  font-size: 18px;
  font-weight: 700;
}
.xt-root::after {
  content: "the\Aqoo";
  white-space: pre;
  position: absolute;
  top: 11px; left: 14px;
  width: 30px; height: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  border-radius: 5px;
  background: #fff;
  color: #3b4f76;
  font-size: 10px;
  font-weight: 800;
  line-height: 1;
}

/* 内容区：块级流 + 可滑动 + 楼层计数器 */
.xt-root .xt-content {
  display: block;
  padding: 0 16px 14px;
  counter-reset: floor;
  max-height: calc(62vh - 52px);
  overflow-y: auto;
  overflow-x: hidden;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
}
.xt-root .xt-content::-webkit-scrollbar { display: none; }

.xt-root .xt-text,
.xt-root .xt-tags,
.xt-root .xt-tag {
  background: none;
  border: 0;
  box-shadow: none;
  border-radius: 0;
  padding: 0;
  margin: 0;
  text-align: left;
}
.xt-root .xt-tags {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 8px;
  margin-top: 8px;
}

/* 浅蓝分类条（吸顶） */
.xt-root .xt-text-boardTag {
  margin: 0 -16px 18px;
  padding: 0 16px;
  height: 44px;
  line-height: 44px;
  background: #7086a9;
  color: #eef2f8;
  font-size: 15px;
  position: sticky;
  top: 0;
  z-index: 2;
}

/* 标题（行内，翻译紧跟在同一行） */
.xt-root .xt-text-postTitle {
  display: inline;
  font-size: 15px;
  font-weight: 700;
  line-height: 1.7;
  color: #222;
}

/* 发帖行：网址 + 무명의 더쿠 | 日期 | 时间 | 조회 수（日期、时间自动读取系统） */
.xt-root .xt-tags::before {
  content: "https://theqoo.net/hot/4181007722";
  flex-basis: 100%;
  font-size: 13px;
  color: #9a9a9a;
  word-break: break-all;
}
.xt-root .xt-tag-currentDate,
.xt-root .xt-tag-currentTime,
.xt-root .xt-tag-views {
  font-size: 12.5px;
  color: #aaa;
}
.xt-root .xt-tag-currentDate::before { content: "무명의 더쿠 | "; }
.xt-root .xt-tag-currentTime::before { content: "| "; }
.xt-root .xt-tag-views::before { content: "| 조회 수 "; }

/* 通栏细分隔线（正文下方） */
.xt-root .xt-divider {
  height: 0;
  border: 0;
  border-top: 1px solid #e8e8e8;
  background: none;
  margin: 14px -16px 0;
}

/* 正文 */
.xt-root .xt-text-postBody {
  font-size: 13px;
  line-height: 1.85;
  color: #222;
  white-space: pre-wrap;
  margin: 8px 0 10px;
}

/* 评论：每条自带分隔线 + 楼号 + 무명의 더쿠（评论为空时整条消失，楼号自动连续） */
.xt-root .xt-text[class*="xt-text-c"]:not([class*="CN"]) {
  display: block;
  counter-increment: floor;
  margin: 0 -16px;
  padding: 14px 16px 4px;
  border-top: 1px solid #e8e8e8;
  font-size: 13px;
  line-height: 1.7;
  color: #777;
}
.xt-root .xt-text[class*="xt-text-c"]:not([class*="CN"])::before {
  content: counter(floor) ". 무명의 더쿠";
  display: block;
  margin-bottom: 6px;
  font-size: 15px;
  font-weight: 700;
  line-height: 1.4;
  color: #222;
}

/* 翻译：黑底白字，逐行贴字的高亮条（标题、正文、所有评论通用） */
.xt-root .xt-text[class*="CN"] {
  display: inline;
  background: #000;
  color: #fff;
  padding: 1px 4px;
  line-height: 1.45;
  font-weight: 500;
  font-size: 14px;
  -webkit-box-decoration-break: clone;
  box-decoration-break: clone;
}
.xt-root .xt-text.xt-text-postTitleCN { font-size: 19px; margin-left: 6px; }
.xt-root .xt-text.xt-text-postBodyCN { font-size: 15.5px; }

/* 空元素隐藏 */
.xt-root .xt-text:empty,
.xt-root .xt-tag:empty {
  display: none;
}

