xinshengCustomCss:
/*⁣‍‌‌⁠‍‍⁠​​‌⁠​‌​​⁠⁠⁠‍‍⁠​​⁠⁠⁠​‍‌‌⁠⁠‍‌‌​‍⁠⁠​⁠‌⁠​‍⁠‌⁠‌‌​‍​‌‌‍‌⁠​‌‍‍‌​⁣ ================= 1. 重置与容器 ================= */
.xt-root * { box-sizing: border-box !important; }
.xt-header, .xt-badge, .xt-grid, .xt-section, .xt-toggle, .xt-action-1, .xt-action-2 { display: none !important; }
.xt-text { margin: 0 !important; padding: 0 !important; border: none !important; display: block !important; box-shadow: none !important; white-space: pre-wrap !important; outline: none !important; font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", sans-serif !important; background: transparent !important; }
.xt-root::-webkit-scrollbar, .xt-text::-webkit-scrollbar { display: none !important; width: 0 !important; }

/* 根容器 */
.xt-root {
    width: 370px !important; 
    height: 720px !important; 
    overflow: hidden !important;
    background-color: #111111 !important;
    background-image: url('https://i.postimg.cc/4xfXH8L1/IMG-5135.jpg') !important;
    background-position: center !important;
    background-size: cover !important;
    background-repeat: no-repeat !important;
    border-radius: 16px !important; 
    position: relative !important; 
    margin: 20px auto !important;
    box-shadow: 0 10px 30px rgba(0,0,0,0.1) !important;
    display: block !important; 
    padding-left: 20px !important;
    padding-right: 50px !important;
    cursor: pointer !important;
}

.xt-root::before {
    content: '' !important;
    position: absolute !important; 
    top: 0 !important; left: 0 !important; 
    width: 100% !important; height: 100% !important;
    background: linear-gradient(to bottom, rgba(0,0,0,0.8) 0%, rgba(0,0,0,0.1) 18%, rgba(0,0,0,0) 50%, rgba(0,0,0,0.2) 80%, rgba(0,0,0,0.85) 100%) !important;
    pointer-events: none !important;
    z-index: 1 !important;
}

/* ================= 1.5 动态四段进度条 ================= */
.xt-root::after {
    content: '' !important;
    position: absolute !important;
    top: 15px !important; 
    left: 15px !important; 
    right: 15px !important; 
    height: 2.5px !important;
    border-radius: 2px !important;
    z-index: 5 !important;
    pointer-events: none !important;

    background-image: 
        linear-gradient(#ffffff, #ffffff),
        linear-gradient(rgba(255,255,255,0.35), rgba(255,255,255,0.35)) !important;
    background-repeat: no-repeat !important;
    background-position: left center, left center !important;
    background-size: 0% 100%, 100% 100%; 

    -webkit-mask-image: linear-gradient(to right,
        #000 0%, #000 23.5%,
        transparent 23.5%, transparent 25.5%,
        #000 25.5%, #000 49%,
        transparent 49%, transparent 51%,
        #000 51%, #000 74.5%,
        transparent 74.5%, transparent 76.5%,
        #000 76.5%, #000 100%
    ) !important;
    mask-image: linear-gradient(to right,
        #000 0%, #000 23.5%,
        transparent 23.5%, transparent 25.5%,
        #000 25.5%, #000 49%,
        transparent 49%, transparent 51%,
        #000 51%, #000 74.5%,
        transparent 74.5%, transparent 76.5%,
        #000 76.5%, #000 100%
    ) !important;

    animation: xtStoryProgress 15s linear infinite !important;
}

@keyframes xtStoryProgress {
    0% { background-size: 0% 100%, 100% 100%; }
    100% { background-size: 100% 100%, 100% 100%; }
}
@-webkit-keyframes xtStoryProgress {
    0% { background-size: 0% 100%, 100% 100%; }
